{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": [
    "config:best-practices"
  ],
  "github-actions": {
    "managerFilePatterns": ["/(^|/)\\.depot/(?:workflows|actions)/.+\\.ya?ml$/"]
  },
  "pre-commit": {
    "enabled": true
  },
  "customManagers": [
    {
      "description": "UV_VERSION and PYTHON_VERSION in the Depot workflows, marked with a renovate comment",
      "customType": "regex",
      "managerFilePatterns": ["/(^|/)\\.depot/(?:workflows|actions)/.+\\.ya?ml$/"],
      "matchStrings": [
        "# renovate: datasource=(?<datasource>\\S+) depName=(?<depName>\\S+)\\s+(?:UV|PYTHON)_VERSION: \"(?<currentValue>[^\"]+)\""
      ]
    }
  ],
  "lockFileMaintenance": {
    "enabled": true,
    "automerge": true
  },
  "packageRules": [
    {
      "description": "Automerge minor and patch updates once CI passes; majors still need a human",
      "matchUpdateTypes": ["minor", "patch"],
      "minimumReleaseAge": "3 days",
      "automerge": true
    },
    {
      "description": "ruff is pinned in pyproject.toml and pre-commit; test_tool_versions.py needs them to move together",
      "matchDepNames": ["ruff", "astral-sh/ruff-pre-commit"],
      "groupName": "ruff"
    },
    {
      "description": "UV_VERSION in ci.yml tracks the same tags as the uv-pre-commit rev; test_tool_versions.py needs them to move together, so one PR bumps both",
      "matchDepNames": ["astral-sh/uv-pre-commit"],
      "groupName": "uv"
    },
    {
      "description": "Python is pinned exactly in pyproject.toml and ci.yml; test_tool_versions.py needs them to move together, so one PR bumps both",
      "matchDepNames": ["python"],
      "groupName": "python",
      "separateMinorPatch": true
    },
    {
      "description": "Stay on the current Python minor; a new minor is a deliberate upgrade",
      "matchDepNames": ["python"],
      "matchUpdateTypes": ["major", "minor"],
      "enabled": false
    }
  ]
}

